/**
 * Purpose: Handles client-side passkey registration using the browser's WebAuthn API.
 * 
 * Description: Takes the registration options from the server, converts them to the proper format for the WebAuthn API, prompts the user to create a credential using their authenticator (fingerprint, Face ID, security key, etc.), and returns the credential data to be verified by the server.
 * 
 *  Returns: Promise - JSON string containing the credential response with:
 *   - Credential ID and raw ID
 *   - Attestation object
 *   - Client data JSON
 *   - All data properly base64url encoded
 * 
 *   Usage Notes:
 *   - Must be called in a secure context (HTTPS)
 *   - Requires user interaction (button click, etc.)
 *   - Will prompt user to use their authenticator device
 *   - Handles common WebAuthn errors with user-friendly messages
 *   - Sets error messages on the registrationRequest object if registration fails
 *   - Supports various authenticator types: platform (Touch ID, Windows Hello) and roaming (USB keys)
 * 
 *   Error Handling:
 *   - Maps technical WebAuthn errors to user-friendly messages
 *   - Updates the registrationRequest with Message and MessageType on error
 *   - Common errors handled: NotAllowedError, SecurityError, InvalidStateError, etc.
 * @param {MxObject} registrationRequest - The RegistrationRequest object from StartRegistration containing:
    - RequestJSON: WebAuthn options from the server
    - User information and challenge data
 * @returns {Promise.<string>}
 */
export async function JS_RegistrationRequest_RegisterInClient(registrationRequest) {
	// BEGIN USER CODE
	try {
		const fullRegistrationOptions = JSON.parse(registrationRequest.get("RequestJSON"));
		
		// Extract the publicKey object - this is what WebAuthn API expects
		const registrationOptions = fullRegistrationOptions.publicKey;
				
		// Validate required fields
		if (!registrationOptions.challenge) {
			throw new Error("Missing challenge in registration options");
		}
		if (!registrationOptions.user || !registrationOptions.user.id) {
			throw new Error("Missing user.id in registration options");
		}
		
		// Convert base64url strings to Uint8Array for WebAuthn API
		const publicKeyCredentialCreationOptions = {
			...registrationOptions,
			challenge: base64urlToUint8Array(registrationOptions.challenge),
			user: {
				...registrationOptions.user,
				id: base64urlToUint8Array(registrationOptions.user.id)
			}
		};

		// Convert excludeCredentials if present
		if (registrationOptions.excludeCredentials && registrationOptions.excludeCredentials.length > 0) {
			publicKeyCredentialCreationOptions.excludeCredentials = registrationOptions.excludeCredentials.map(cred => {
				if (!cred.id) {
					throw new Error("Missing id in excludeCredentials");
				}
				return {
					...cred,
					id: base64urlToUint8Array(cred.id)
				};
			});
		}
		
		// Call WebAuthn API
		const credential = await navigator.credentials.create({
			publicKey: publicKeyCredentialCreationOptions
		});
		
		if (!credential) {
			throw new Error("Failed to create credential");
		}
		
		// Convert response to JSON with proper base64url encoding
		const credentialJson = JSON.stringify({
			id: credential.id,
			rawId: uint8ArrayToBase64url(new Uint8Array(credential.rawId)),
			response: {
				attestationObject: uint8ArrayToBase64url(new Uint8Array(credential.response.attestationObject)),
				clientDataJSON: uint8ArrayToBase64url(new Uint8Array(credential.response.clientDataJSON))
			},
			type: credential.type
		});
		
		return credentialJson;
		
	} catch (error) {
		handleWebAuthnError(error, registrationRequest);
	}
	
	// END USER CODE
}
